import{z as s,x as l,o as e,c as d,q as t,j as i,D as a,d as B,s as r,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"助推与选择架构","description":"","frontmatter":{"title":"助推与选择架构","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/nudge-choice-architecture.md","filePath":"econ/nudge-choice-architecture.md","lastUpdated":1791063341000}'),p={name:"econ/nudge-choice-architecture.md"};function c(h,E,C,m,u,D){const A=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="助推与选择架构" tabindex="-1">助推与选择架构 <a class="header-anchor" href="#助推与选择架构" aria-label="Permalink to &quot;助推与选择架构&quot;">​</a></h1><div class="epigraph"><p>菜单的排列、默认和反馈改变选择，而不关掉任何选项——自由保留，统计不保留。</p><footer>—— Thaler and Sunstein, Nudge, 2008；对照 Johnson and Goldstein, Science 2003；Madrian and Shea, QJE 2001</footer></div><p><a href="/econ/social-preferences">上一课</a>把别人写进效用。本课缺口是设计：若偏好依赖框架、默认和满意停点，则架构是政策变量。不重写 401(k) 的数字，只把家庭金融那一课升成一般选择架构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准公共经济学改预算（税、补贴）或改可行集（禁令）。助推改的是描述与默认，菜单在法律上仍全在。Johnson 与 Goldstein（2003）：器官捐献默认从退出改为进入，登记率跳跃。Madrian–Shea 已见退休账户。Thaler 与 Sunstein 称之为自由家长主义：不强迫，但预测行为被推往某方向。缺口是承认<a href="/econ/framing-effects">框架</a>与<a href="/econ/bounded-rationality-satisficing">满意</a>之后，中性菜单并不存在——总有一种默认。</p><p><span class="marginnote">数字感受默认的力量：Johnson 与 Goldstein 比较各国器官捐献登记率，「默认同意」的国家常在九成上下，「默认不同意」的国家只有百分之几——法律条文几乎一样，差的只是预先勾选的那一小格。</span></p><p><span class="marginnote">中性架构是幻觉：选项总要有一个预先勾选、总要有一个先出现在屏幕上。问题不是「是否助推」，是朝哪推、谁来选方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：默认、简化、社会比较反馈、承诺装置的可选版本、显著性标记。评价：在不减少选项的约束下，目标行为的统计变化。本课不做法哲学裁决。与税的比较：税改相对价格，助推改编码与搜索顺序。</p>',9)),(e(),i(o,null,{default:a(()=>[r(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E6%A1%86%E6%9E%B6%E4%B8%8E%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20CA%5B%22%E9%80%89%E6%8B%A9%E6%9E%B6%E6%9E%84%E6%80%BB%E5%AD%98%E5%9C%A8%22%5D%0A%20%20CA%20--%3E%20NUD%5B%22%E5%8A%A9%E6%8E%A8%3A%20%E4%B8%8D%E5%87%8F%E9%80%89%E9%A1%B9%2C%20%E6%94%B9%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20NUD%20--%3E%20EX%5B%22%E5%99%A8%E5%AE%98%E6%8D%90%E7%8C%AE%20%2F%20%E9%80%80%E4%BC%91%E7%BC%B4%E5%AD%98%20%2F%20%E9%82%BB%E5%B1%85%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[B("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"机制是把决策停在架构指定的点。满意者停在默认；损失厌恶者把默认当参考点，离开它被编码为损失；社会偏好者响应邻居比较。同一工具对不同零件生效，不必先估计 \\(\\lambda\\)。家庭金融课已经用过默认；本课只声明它是一般技术。",-1)),(e(),i(o,null,{default:a(()=>[r(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E8%AE%BE%E8%AE%A1%E8%80%85%E6%8A%8A%E7%9B%AE%E6%A0%87%E9%80%89%E9%A1%B9%E8%AE%BE%E4%B8%BA%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20CH%7B%22%E7%94%A8%E6%88%B7%E9%9D%A0%E5%93%AA%E7%A7%8D%E9%9B%B6%E4%BB%B6%E5%A4%84%E7%90%86%E8%8F%9C%E5%8D%95%EF%BC%9F%22%7D%0A%20%20CH%20--%3E%7C%22%E6%BB%A1%E6%84%8F%EF%BC%9A%E4%B8%8D%E6%83%B3%E8%B4%B9%E7%A5%9E%22%7C%20STAY%5B%22%E6%87%92%E5%BE%97%E6%AF%94%E8%BE%83%EF%BC%8C%E5%81%9C%E5%9C%A8%E9%BB%98%E8%AE%A4%22%5D%0A%20%20CH%20--%3E%7C%22%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%EF%BC%9A%E9%BB%98%E8%AE%A4%E6%98%AF%E5%8F%82%E8%80%83%E7%82%B9%22%7C%20LOSS%5B%22%E7%A6%BB%E5%BC%80%E9%BB%98%E8%AE%A4%E8%A2%AB%E7%BC%96%E7%A0%81%E4%B8%BA%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20CH%20--%3E%7C%22%E7%A4%BE%E4%BC%9A%E6%AF%94%E8%BE%83%EF%BC%9A%E7%9C%8B%E5%88%B0%E9%82%BB%E5%B1%85%E6%80%8E%E4%B9%88%E5%81%9A%22%7C%20SOC%5B%22%E5%90%91%E5%A4%9A%E6%95%B0%E7%9C%8B%E9%BD%90%22%5D%0A%20%20STAY%20--%3E%20R%5B%22%E7%BB%9F%E8%AE%A1%E4%B8%8A%E5%A4%9A%E6%95%B0%E4%BA%BA%E8%A2%AB%E6%8E%A8%E5%BE%80%E9%BB%98%E8%AE%A4%E6%96%B9%E5%90%91%22%5D%0A%20%20LOSS%20--%3E%20R%0A%20%20SOC%20--%3E%20R%0A%20%20NOTE%5B%22%E6%B3%95%E5%BE%8B%E4%B8%8A%E4%BB%BB%E4%BD%95%E9%80%89%E9%A1%B9%E4%BB%8D%E5%8F%AF%E6%89%8B%E5%8A%A8%E6%9B%B4%E6%94%B9%22%5D%20-.-%3E%20DEF%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：默认像自助餐里已经摆上你盘子的第一勺菜。你可以换（选项都还在），但换盘要动手、要动脑，多数人就着这勺吃完了——助推没有禁止什么，只是把「什么都不做」的结局设成了设计者想要的方向。</span></p><p>不进入限价簿的默认价格档。交易所的 tick 与保护订单是协议设计，属量化栏。</p><p>Madrian–Shea 已在家庭金融出现；本课把它升成一般命题：只要满意与损失厌恶还在，默认就是实质菜单。器官捐献的进入/退出默认证明同一技术跨出退休账户。税改相对价格，人人面对新预算；助推改编码，法律菜单不变。中性架构不存在——总有一种先勾选。方向由谁选，是政治，不是本课的一阶条件。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>助推可被用来抽取而非帮助（暗模式）。长期习惯形成可能使效应衰减。信息性标签若实际上改变了信念，就不是纯框架。本课不把所有政策效果称为助推。显著性与注意力是下一课：有些「助推」其实是把被忽略的属性点亮。</p><p><span class="marginnote">常见误区：以为助推是「零成本、无副作用」的政策。同一套零件也能做暗模式——把退订入口藏进三级菜单同样是改默认。评价一项架构要看它是在降低还是抬高用户的搜索成本；方向本身仍是价值选择，不是技术问题。</span></p><p>后课默认：选择架构是行为公共财政的工具箱；注意力模型给它提供另一条微观基础。</p><p>中性架构是幻觉：总有一种默认、总有一个先出现的选项。问题是朝哪推。</p><p>税改相对价格；助推改编码。器官捐献与 401(k) 是同一技术的两个现场。</p><p><span class="marginnote">本课不做方向上的哲学裁决；只标明架构是政策变量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>架构不可避免；助推在不减选项时移动统计。</li><li>默认、简化、社会比较，分别调用惰性、满意与社会偏好。</li><li>与税分工：一个改价格，一个改编码。</li><li>暗模式用同一零件抽取而非帮助。</li><li>显著性下一课解释有些标签其实是点亮属性。</li><li>出处：Johnson and Goldstein, <em>Science</em> 2003；Thaler and Sunstein, 2008。</li></ul>',12))])}const _=s(p,[["render",c]]);export{S as __pageData,_ as default};
